func newWorkflowArchiveCmd(flags *rootFlags) *cobra.Command {
	var dbPath string
	var full bool
	var maxPages int
	var unbounded bool

	cmd := &cobra.Command{
		Use:   "archive",
		Short: "Sync all resources to local store for offline access and search",
		Long: `Archive fetches a bounded page from each syncable resource and stores it in a
local SQLite database. By default it limits every resource to one page so an
archive is safe to run against large public datasets. Use --max-pages for a
larger bounded archive, or --unbounded (equivalently --max-pages 0) only when you deliberately want every
available page. Credential-only resources are omitted when no credential is configured.
After archiving, use 'search' for instant full-text search.`,
		Example: `  # Archive one page per available resource (safe default)
  inaturalist-pp-cli workflow archive


  # Re-archive with up to five pages per resource
  inaturalist-pp-cli workflow archive --full --max-pages 5

  # Deliberately archive every available page
  inaturalist-pp-cli workflow archive --unbounded`,
		RunE: func(cmd *cobra.Command, args []string) error {
			c, err := flags.newClient()
			if err != nil {
				return err
			}
			c.NoCache = true
			resources, effectiveMaxPages, err := workflowArchivePlan(c.Config.AuthHeader() != "", maxPages, unbounded)
			if err != nil {
				return err
			}

			if dbPath == "" {
				dbPath = defaultDBPath("inaturalist-pp-cli")
			}
			s, err := store.OpenWithContext(cmd.Context(), dbPath)
			if err != nil {
				return fmt.Errorf("opening store: %w", err)
			}
			defer s.Close()

			totalSynced := 0
			syncEventWriter := cmd.OutOrStdout()
			if flags.asJSON {
				syncEventWriter = cmd.ErrOrStderr()
			}

			// --full clears the cursor here because syncResource reads
			// existingCursor unconditionally; its full param only gates the
			// since filter, not cursor reset. Mirrors newSyncCmd's pattern.
			if full {
				for _, resource := range resources {
					_ = s.SaveSyncState(resource, "", 0)
				}
			}

			for _, resource := range resources {
				res := syncResource(cmd.Context(), c, s, resource, "", full, effectiveMaxPages, false, false, nil, syncEventWriter)
				if res.Err != nil {
					fmt.Fprintf(cmd.ErrOrStderr(), "  %s: error: %v\n", resource, res.Err)
					continue
				}
				if res.Warn != nil {
					fmt.Fprintf(cmd.ErrOrStderr(), "  %s: warning: %v\n", resource, res.Warn)
					continue
				}
				totalSynced += res.Count
				fmt.Fprintf(cmd.ErrOrStderr(), "  %s: %d synced\n", resource, res.Count)
			}

			if flags.asJSON {
				enc := json.NewEncoder(cmd.OutOrStdout())
				enc.SetIndent("", "  ")
				return enc.Encode(map[string]any{
					"resources_synced": len(resources),
					"total_items":      totalSynced,
					"store_path":       dbPath,
					"timestamp":        time.Now().UTC().Format(time.RFC3339),
				})
			}

			fmt.Fprintf(cmd.OutOrStdout(), "Archived %d items across %d resources to %s\n", totalSynced, len(resources), dbPath)
			return nil
		},
	}

	cmd.Flags().StringVar(&dbPath, "db", "", "SQLite database file path (default: resolved data directory data.db)")
	cmd.Flags().BoolVar(&full, "full", false, "Ignore prior archive cursors before the bounded archive")
	cmd.Flags().IntVar(&maxPages, "max-pages", workflowArchiveDefaultMaxPages, "Maximum pages per resource (0 for unlimited; default 1)")
	cmd.Flags().BoolVar(&unbounded, "unbounded", false, "Archive every page of each available resource; may take significant time")

	return cmd
}

